package com.hbm.machine.forcefield;
import com.google.gson.*;import com.mojang.logging.LogUtils;import java.math.BigInteger;import java.nio.file.*;import net.neoforged.fml.loading.FMLPaths;
/** All9 actual source hbmMachines.json.forcefield values. HE capacity uses the native exact integer path. */
public final class ForceFieldConfig {
 public static BigInteger maxPower=BigInteger.valueOf(1000000);public static int baseCon=1000,radCon=500,shCon=250,baseRadius=16,radUpgrade=16,shUpgrade=50;public static double cooldownModif=1,healthRegenModif=1;
 public static void load(){Path path=FMLPaths.CONFIGDIR.get().resolve("hbmConfig/hbmMachines.json");try{Files.createDirectories(path.getParent());JsonObject root=new JsonObject();if(Files.isRegularFile(path))try(var reader=Files.newBufferedReader(path)){root=JsonParser.parseReader(reader).getAsJsonObject();}var machine=root.has("forcefield")?root.getAsJsonObject("forcefield"):new JsonObject();if(machine.has("L:powerCap"))maxPower=machine.get("L:powerCap").getAsBigInteger();if(machine.has("I:baseConsumption"))baseCon=machine.get("I:baseConsumption").getAsInt();if(machine.has("I:radiusConsumption"))radCon=machine.get("I:radiusConsumption").getAsInt();if(machine.has("I:shieldConsumption"))shCon=machine.get("I:shieldConsumption").getAsInt();if(machine.has("I:baseRadius"))baseRadius=machine.get("I:baseRadius").getAsInt();if(machine.has("I:radiusUpgrade"))radUpgrade=machine.get("I:radiusUpgrade").getAsInt();if(machine.has("I:shieldUpgrade"))shUpgrade=machine.get("I:shieldUpgrade").getAsInt();if(machine.has("D:cooldownModifier"))cooldownModif=machine.get("D:cooldownModifier").getAsDouble();if(machine.has("D:healthRegenModifier"))healthRegenModif=machine.get("D:healthRegenModifier").getAsDouble();machine.addProperty("L:powerCap",maxPower);machine.addProperty("I:baseConsumption",baseCon);machine.addProperty("I:radiusConsumption",radCon);machine.addProperty("I:shieldConsumption",shCon);machine.addProperty("I:baseRadius",baseRadius);machine.addProperty("I:radiusUpgrade",radUpgrade);machine.addProperty("I:shieldUpgrade",shUpgrade);machine.addProperty("D:cooldownModifier",cooldownModif);machine.addProperty("D:healthRegenModifier",healthRegenModif);root.add("forcefield",machine);Files.writeString(path,new GsonBuilder().setPrettyPrinting().create().toJson(root)+"\n");}catch(Exception error){LogUtils.getLogger().error("Cannot load original forcefield configuration",error);}}
 private ForceFieldConfig(){}
}
